// Bring-up sketch, built only by [env:bringup]. Regenerated on every run; do not edit.
// Prints the pin map, scans I2C, checks the outputs, then reports inputs every second.
// Every output is first put at its idle level. Only parts whose part file marks them safe
// (an LED, a buzzer) are switched on for 400 ms. Relays, servos, motor drivers and data
// lines are held at idle and named on the serial port: test those from main.cpp, load disconnected.
#include <Arduino.h>
#include <Wire.h>
#include "pins.h"

struct Expect {
  const char* part;
  const uint8_t* addrs;
  uint8_t count;
};
static const uint8_t ADDRS_0[] = {0x48, 0x49, 0x4A, 0x4B};
static const Expect EXPECTED[] = {
  {"ADS1115 16-Bit ADC - 4 Channel with Programmable Gain Amplifier (ads)", ADDRS_0, 4},
};

static void printPinMap() {
  Serial.println("[pins] pin map from pins.h");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_STEP", PIN_STEP, "STEP: drv.PUL+");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_DIR", PIN_DIR, "DIR: drv.DIR+");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_ENA", PIN_ENA, "ENA: drv.ENA+");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_DRIVER_ALM", PIN_DRIVER_ALM, "DRIVER_ALM: drv.ALM+");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_POT", PIN_POT, "POT: pot.2");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_DIR_SWITCH", PIN_DIR_SWITCH, "DIR_SWITCH: dirsw.COM");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_ESTOP", PIN_ESTOP, "ESTOP: estop.2");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_I2C_SDA", PIN_I2C_SDA, "I2C_SDA: ads.SDA");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_I2C_SCL", PIN_I2C_SCL, "I2C_SCL: ads.SCL");
  Serial.printf("  %-18s GPIO%-3d %s\n", "PIN_PEDAL_SW", PIN_PEDAL_SW, "PEDAL_SW: pedal.4");
}

static bool probe(uint8_t addr) {
  Wire.beginTransmission(addr);
  return Wire.endTransmission() == 0;
}

static void scanI2c() {
  Wire.begin(PIN_I2C_SDA, PIN_I2C_SCL);
  Serial.println("[i2c] scanning 0x08-0x77");
  bool seen[128] = {false};
  int count = 0;
  for (uint8_t a = 0x08; a <= 0x77; a++) {
    if (probe(a)) {
      seen[a] = true;
      count++;
      Serial.printf("  device at 0x%02X\n", a);
    }
  }
  if (count == 0) Serial.println("  nothing answered: check 3V3, GND, SDA/SCL and that the pins are not swapped");
  for (const Expect& e : EXPECTED) {
    int hit = -1;
    for (uint8_t i = 0; i < e.count; i++) {
      if (seen[e.addrs[i]]) { hit = e.addrs[i]; break; }
    }
    if (hit >= 0) Serial.printf("[ OK ] %s found at 0x%02X\n", e.part, hit);
    else {
      Serial.printf("[MISS] %s missing, expected at", e.part);
      for (uint8_t i = 0; i < e.count; i++) Serial.printf(" 0x%02X", e.addrs[i]);
      Serial.println();
    }
  }
}

void setup() {
  // Outputs to their idle level first: until here they float, and a driver input may read that as on.
  gpio_set_level((gpio_num_t)PIN_STEP, 0);
  pinMode(PIN_STEP, OUTPUT);
  digitalWrite(PIN_STEP, LOW);
  gpio_set_level((gpio_num_t)PIN_DIR, 0);
  pinMode(PIN_DIR, OUTPUT);
  digitalWrite(PIN_DIR, LOW);
  gpio_set_level((gpio_num_t)PIN_ENA, 1);
  pinMode(PIN_ENA, OUTPUT);
  digitalWrite(PIN_ENA, HIGH);
  Serial.begin(115200);
  uint32_t t0 = millis();
  while (!Serial && millis() - t0 < 3000) delay(10);
  delay(300);
  Serial.println("\n=== bring-up: tig-rotator-controls ===");
  printPinMap();
  scanI2c();
  Serial.println("[out] PIN_STEP GPIO50 held LOW, not switched: DM542T signal terminal (drv). Reason: its part file does not mark it as safe to switch in a test (kind: actuator).");
  Serial.println("[out] PIN_DIR GPIO51 held LOW, not switched: DM542T signal terminal (drv). Reason: its part file does not mark it as safe to switch in a test (kind: actuator).");
  Serial.println("[out] PIN_ENA GPIO52 held HIGH, not switched: DM542T signal terminal (drv). Reason: its part file does not mark it as safe to switch in a test (kind: actuator).");
  pinMode(PIN_DRIVER_ALM, INPUT_PULLUP);
  pinMode(PIN_DIR_SWITCH, INPUT_PULLUP);
  pinMode(PIN_ESTOP, INPUT_PULLUP);
  pinMode(PIN_PEDAL_SW, INPUT_PULLUP);
  Serial.println("[in] reporting inputs once a second");
}

void loop() {
  Serial.printf("[in] t=%lus", (unsigned long)(millis() / 1000));
  Serial.printf(" PIN_DRIVER_ALM=%d", digitalRead(PIN_DRIVER_ALM));
  Serial.printf(" PIN_POT=%d", analogRead(PIN_POT));
  Serial.printf(" PIN_DIR_SWITCH=%d", digitalRead(PIN_DIR_SWITCH));
  Serial.printf(" PIN_ESTOP=%d", digitalRead(PIN_ESTOP));
  Serial.printf(" PIN_PEDAL_SW=%d", digitalRead(PIN_PEDAL_SW));
  Serial.println();
  delay(1000);
}
